#!/usr/bin/env python3
from pathlib import Path
import json
R=Path(__file__).resolve().parents[1]
def read(n):return [json.loads(x) for x in (R/n).read_text().splitlines() if x.strip()]
def frac(m):return f"{m['numerator']}/{m['denominator']} ({100*m['rate']:.1f}%)" if m['rate'] is not None else f"{m['numerator']}/{m['denominator']} (undefined)"
def show(d):return f"{d['action']} / {d['determination']}"
s=json.loads((R/'results/summary.json').read_text());pairs={x['id']:x for x in read('data/pairs.jsonl')};ps=read('results/pair_scores.jsonl');errors=read('results/errors.jsonl');meta=json.loads((R/'results/predictions.metadata.json').read_text());qa=json.loads((R/'audit/independent_result_check.json').read_text());assert qa['passed']
lines=['# German minimal-change paired results','',f"Independent final audit passed with {qa['prediction_count']} native predictions and no reported mismatches. All 50 frozen files remain unchanged.",'','## Primary finite-set results','',f"- Complete two-field case accuracy: {frac(s['case_metrics']['all_fields_exact'])}",f"- Both members fully correct: {frac(s['pair_metrics']['both_correct'])}",f"- Correct full directional transition on outcome-changing pairs: {frac(s['pair_metrics']['correct_directional_change'])}",f"- Observed output changes on flip pairs, irrespective of correctness: {frac(s['pair_metrics']['observed_change_on_flip'])}",f"- Unjustified output changes on outcome-invariant pairs: {frac(s['pair_metrics']['unjustified_change'])}",f"- Stable invariant pairs: {frac(s['pair_metrics']['stable_invariant'])}",f"- Stable but not fully correct invariant pairs: {frac(s['pair_metrics']['stable_but_incorrect'])}",f"- Technical invalid/missing cases: {48-s['technical']['valid_cases']}/48",'', 'A changed output alone is not a correct transition: both two-field endpoints must match their respective gold. Stable wrong outputs are separately counted. Pairwise observations are dependent; these are exact counts for this finite authored diagnostic, not population estimates.','', '## Domain and pair-kind counts','', '| Group | Both-correct pairs |', '|---|---:|']
for kind in ['domain','kind','subtype']:
 for label,v in s['pair_strata'][kind].items():lines.append(f"| {kind}: {label} | {frac(v['both_correct'])} |")
lines+=['','## Runtime and exclusions','',f"Pinned official 9B Cloudflare/clef-flash revision {meta['revision']}. {meta['mode']}. Six CPU threads, batch 1, maximum 2048 input tokens. Original native model code and runner unchanged. No GPU or unquantized baseline was run.",'',f"- Input tokens: {s['technical']['input_tokens_min']}–{s['technical']['input_tokens_max']}; cap-versus-uncapped equality verified for every request",f"- Median forward time: {s['technical']['forward_seconds_median']:.3f}s; p95: {s['technical']['forward_seconds_p95']:.3f}s",f"- Total benchmark forward time: {s['technical']['forward_seconds_total']:.3f}s",f"- Model load time: {meta['load_seconds']:.3f}s",f"- Peak RSS observed in benchmark rows: {s['technical']['peak_observed_rss_bytes']/1024**3:.3f} GiB",f"- Single-case repeatability summary: maximum absolute probability difference {meta['repeatability_probe']['repeat_max_absolute_probability_difference']}; same native answer: {meta['repeatability_probe']['same_choice']}",'','The native execution log reported unavailable optional CPU GEMM/attention fast paths and fallback implementations; results/runtime_observations.json preserves these public-essential observations. The unrelated technical warmup and one first-case repeat probe are excluded from quality and benchmark forward-time aggregates. The original runner retains a warmup result and repeatability summary but does not expose the repeat’s separate full probability vector/timing. A single-case probe does not establish general determinism. Marginal native softmax values are not calibrated or joint probabilities.','', '## Error pairs','']
for p in ps:
 if p['both_correct']:continue
 data=pairs[p['id']];lines += [f"### {p['id']}",f"- Kind: {p['kind']} / {p['subtype']}",f"- Changed fact: {data['changed_fact']}",f"- A: expected {show(p['expected_a'])}; predicted {show(p['predicted_a'])}",f"- B: expected {show(p['expected_b'])}; predicted {show(p['predicted_b'])}",'']
if not s['error_pair_ids']:lines.append('No erroneous pairs in this finite set.')
lines+=['','## Scope and caveats','','AI-authored and separately AI-reviewed with gold visibility, not human-expert validated. Exact schema and generic rule templates are reused from clarification72; all 24 scenario situations/rule texts are new. All edits, original review snapshots and pre-inference corrections are retained. One tariff-scope wording issue was corrected. Four other pre-run pair refinements reduce direction/outcome confounds; some gold endpoints changed before any model output existed. No outcome-driven correction or rerun selection occurred.','','Eight pairs per domain; most subtype×domain cells have only one pair, irrelevant-text cells two. The three short-circuit controls are all no/no by construction. Synthetic explicit rules do not represent actual customer cases, banking rules, insurance coverage or financial advice. This tests bounded native decisions, not generated German answer/question quality. No naive independent-case significance tests or pooling with earlier suite scores.','','See PROTOCOL.md, SOURCES.md, results/summary.json, complete native results and independent audit artifacts for reproducible details.']
patterns=[]
ids={e['id'] for e in errors}
if 'pair_gadget_theft_notice_a' in ids:patterns.append('At the explicitly inclusive 48-hour boundary, one endpoint returned answer/unresolved rather than answer/yes.')
if 'pair_statement_notification_a' in ids:patterns.append('Unknown consent was treated as a definite no in one endpoint.')
if {'pair_tow_distance_records_b','pair_redemption_window_conflict_a'} <= ids:patterns.append('Identical 25/25 distance records and identical closed/closed window records still triggered clarification actions in two answerable endpoints.')
if {'pair_report_delivery_target_a','pair_report_delivery_target_b'} <= ids:patterns.append('An irrelevant report-title edit preserved a wrong answer/yes in both variants despite the unresolved target.')
if {'pair_rental_days_conflict_a','pair_rental_days_conflict_b'} <= ids:patterns.append('An irrelevant vehicle-color edit preserved the wrong clarification category in both variants of a conflicting-record case.')
if 'pair_limit_order_price_step_a' in ids:patterns.append('An invalid price increment already forced no, but an unknown trading window triggered ask_fact/unresolved; this pair produced the unjustified invariant change.')
report='\n'.join(lines)+'\n'
if patterns:report=report.replace('## Error pairs','## Observed failure patterns\n\n'+'\n'.join('- '+p for p in patterns)+'\n\nThese describe retained error cases, not general failure-rate estimates. Every endpoint and its unrounded scores are preserved.\n\n## Error pairs')
report += '\n## Audit implementation history\n\nThe independent checker first flagged its own option-map ordering and manifest-schema assumptions. It was corrected against the unmodified native source, regression-tested, and rerun; the corrected checks and a concise methodological correction record remain included; redundant development diagnostics are outside the public package. No frozen input, gold, primary scorer or raw prediction was changed. Final audit passed 6,972 comparisons and 60 independent checker self-tests.\n'
(R/'REPORT.md').write_text(report)
lines=['# All case errors','',f'{len(errors)} incorrect complete two-field cases. No filtering or selective omission. Full native probabilities remain in results/predictions.jsonl and results/errors.jsonl.','']
for e in errors:
 lines += [f"## {e['id']}",f"Pair: {e['pair_id']} ({e['side']})",'',f"Rule: {e['rule']}",'',f"Scenario: {e['message']}",'',f"Question: {e['question']}",'',f"Expected: {show(e['expected'])}",f"Predicted: {show(e['predicted'])}",f"Rationale: {e['rationale']}",f"Technical issues: {e['technical_issues']}",'','Unrounded native option scores:','',json.dumps(e['probabilities_unrounded'],ensure_ascii=False,indent=2),'']
(R/'ERRORS.md').write_text('\n'.join(lines)+'\n')
p=R/'README.md';text=p.read_text();prefix='## Verified result\n\n';start=text.find(prefix)
if start>=0:text=text[:start]
text+='\n'+prefix+f"{frac(s['case_metrics']['all_fields_exact'])} complete cases correct; {frac(s['pair_metrics']['both_correct'])} pairs both-correct; {frac(s['pair_metrics']['correct_directional_change'])} correct directional flips; {frac(s['pair_metrics']['unjustified_change'])} unjustified invariant changes. Independent score/integrity audit passed.\n\nSee [REPORT.md](REPORT.md), [ERRORS.md](ERRORS.md) and [all raw results](results/predictions.jsonl).\n";p.write_text(text)
print('Wrote REPORT.md, ERRORS.md, verified README result')
